'use strict';
const $=id=>document.getElementById(id),pending=new Map();let seq=0,state=Student.empty(),account=null,view='home',tab='lectures',current=null,connection={mode:'offline',available:false},recording=null,recordBase='',paused=false,busy=false,authMode='login',plan='basic',saveTimer,messageTimer,saveChain=Promise.resolve(),cardIndex=0,flipped=false,quiz=null,docPage=0;
const paths={home:'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',courses:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 3v18m4-13h5m-5 4h5"/>',planner:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',study:'<path d="M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Zm9 2v15"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',cards:'<rect x="4" y="6" width="15" height="15" rx="2"/><path d="M8 2h13v15M8 11h7m-7 4h5"/>',grade:'<path d="m3 7 9-4 9 4-9 4Zm3 3v6c4 4 8 4 12 0v-6m3-3v10"/>',money:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18m-5 5h5"/>',write:'<path d="m15 3 6 6-12 12H3v-6Zm-9 12 6 6"/>',career:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 13h18m-12-2v4h6v-4"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',people:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m2-18a4 4 0 0 1 0 8m1 3a6 6 0 0 1 3 7"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[k]||paths.study}</svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const courseName=id=>state.courses.find(c=>c.id===id)?.name||'Unassigned',lecture=()=>state.lectures.find(l=>l.id===current);
const button=(label,action,id='',cls='secondary')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const item=(title,meta,action,id,symbol='study')=>`<button class="item" data-action="${action}" data-id="${esc(id)}"><span class="symbol">${icon(symbol)}</span><span class="copy"><strong data-no-translate>${esc(title)}</strong><small>${esc(meta)}</small></span><span class="arrow">›</span></button>`;
const empty=text=>`<div class="empty">${text}</div>`,heading=(eyebrow,title,description='')=>`<span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p class="muted">${description}</p>`:''}`;
function call(action,args={}){return new Promise((resolve,reject)=>{if(!window.Native)return reject(Error('Install the Android app for encrypted storage, microphone and file access.'));const id=String(++seq);pending.set(id,{resolve,reject});window.Native.request(JSON.stringify({id,action,args}));});}
function notify(text,error=false){clearTimeout(messageTimer);$('message').textContent=text;$('message').classList.toggle('error',error);$('message').hidden=false;messageTimer=setTimeout(()=>$('message').hidden=true,error?9000:4500);}
async function run(label,fn){if(busy){notify('A task is finishing. You can keep writing in the handwriting panel.');return;}busy=true;$('busyText').textContent=label;$('busy').hidden=false;try{return await fn();}catch(e){notify(e.message||String(e),true);}finally{busy=false;$('busy').hidden=true;}}
function persist(){clearTimeout(saveTimer);if(!account)return Promise.resolve();const copy=JSON.parse(JSON.stringify(state));const work=saveChain.catch(()=>{}).then(()=>call('state.save',{state:copy}));saveChain=work;return work.then(value=>{if($('saved'))$('saved').textContent='Encrypted in this browser';return value;});}
function queueSave(){clearTimeout(saveTimer);$('saved').textContent='Saving…';saveTimer=setTimeout(()=>persist().then(()=>$('saved').textContent='Encrypted in this browser').catch(e=>notify(e.message,true)),450);}
function audit(action){state.activity.unshift({action,at:Student.now()});state.activity=state.activity.slice(0,150);queueSave();}
function confirmation(title,text,label='Confirm'){return new Promise(resolve=>{$('confirmTitle').textContent=title;$('confirmText').textContent=text;$('confirmOk').textContent=label;$('confirmation').showModal();const end=v=>{$('confirmation').close();resolve(v);};$('confirmOk').onclick=()=>end(true);$('confirmCancel').onclick=()=>end(false);$('confirmation').oncancel=e=>{e.preventDefault();end(false);};});}
function applyPreferences(){if(window.I18n)I18n.set(state.profile.uiLanguage||'en');state.profile.fontSize=Student.textSize(state.profile.fontSize);document.body.classList.toggle('dark',state.profile.theme==='dark');document.documentElement.style.fontSize=(Number(state.profile.fontSize)||16)+'px';document.documentElement.style.setProperty('--font-scale',(Number(state.profile.fontSize)||16)/16);}
async function load(){const result=await call('state.load');state=Student.normalize(result.state);if(!result.state?.profile?.uiLanguage&&window.I18n)state.profile.uiLanguage=I18n.language;account=result.account;connection=result.connection||{mode:'offline',available:false};connectionIndicator();$('auth').hidden=true;$('app').hidden=false;applyPreferences();navigate('home');if(state.profile.calendarAuto)syncDeviceCalendars().catch(()=>{});if(!state.profile.educationChosen)openSidebar();if(state.profile.notifications)syncReminders().catch(()=>{});}
function navigate(next,sub){closeSidebar(false);view=next;if(sub)tab=sub;const isLecture=next==='lecture';$('lectureView').hidden=!isLecture;$('screen').hidden=isLecture;renderQuickAccess();if(!isLecture)render();else updateWorkspaceStatus();window.scrollTo(0,0);}
function render(){const pages={home:home,courses:courses,planner:planner,study:study,more:more,grades:grades,budget:budget,writing:writing,career:career,projects:projects,contacts:contacts,focus:focus,tools:tools,settings:settings,handwriting:handwriting,handPage:handPage,accounts:accounts,cloudFiles:cloudFiles,help:help};$('screen').dataset.view=view;$('screen').innerHTML=(pages[view]||home)();bindPage();updateWorkspaceStatus();renderQuickAccess();}
function home(){const pending=state.tasks.filter(t=>t.status!=='done'),upcoming=[...state.events].filter(e=>new Date(e.end||e.start)>=new Date()).sort((a,b)=>a.start.localeCompare(b.start)),due=state.cards.filter(c=>c.due<=Student.day()),name=esc((account.displayName||account.username).split(' ')[0]);return `<div class="dashboard-heading"><div><span class="eyebrow">YOUR DAY, WITH INTENTION</span><h1>Good to see you, ${name}.</h1><p class="muted">Your study day at a glance.</p></div><span class="pill">${esc(new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}))}</span></div><section class="hero dashboard-capture" aria-label="Quick capture"><div><h2>Capture. Organise. Study.</h2><p>Your ideas stay on this device.</p></div><div class="row wrap">${button(icon('mic')+'<span>Record lecture</span>','newLecture','','gold')}${button(icon('study')+'<span>Import material</span>','importDocument','','gold')}${button(icon('write')+'<span>Handwrite</span>','nav','handwriting','gold')}</div></section><div class="metrics dashboard-metrics"><div><b>${state.courses.length}</b><span>Courses</span></div><div><b>${pending.length}</b><span>Open tasks</span></div><div><b>${due.length}</b><span>Cards to review</span></div><div><b>${state.lectures.length}</b><span>Lectures</span></div></div><div class="dashboard-sections"><section class="dashboard-panel"><div class="section-title"><h2>${icon('planner')} On your horizon</h2>${button('Planner →','nav','planner','text-button')}</div>${pending.slice().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,4).map(t=>item(t.title,`${courseName(t.course)} · ${t.due||'No deadline'}`,'taskDetail',t.id,'planner')).join('')||empty('No open assignments.<br>Add a task to plan your next step.')}</section><section class="dashboard-panel"><div class="section-title"><h2>${icon('clock')} Next classes</h2>${button('Timetable →','nav','planner','text-button')}</div>${upcoming.slice(0,3).map(e=>item(e.title,(e.allDay?new Date(e.start).toLocaleDateString()+' · All day':new Date(e.start).toLocaleString())+' · '+(e.location||'Location not set'),'eventDetail',e.id,'clock')).join('')||empty('No upcoming classes.<br>Add your timetable in Planner.')}</section><section class="dashboard-panel"><div class="section-title"><h2>${icon('study')} Recent notes</h2>${button('Library →','nav','study','text-button')}</div>${state.lectures.slice(0,4).map(l=>item(l.title,courseName(l.course)+' · '+l.date,'lecture',l.id,'mic')).join('')||empty('No lecture notes yet.<br>Record or import your material.')}</section></div><div class="section-title"><h2>Study tools</h2>${button('All tools →','nav','more','text-button')}</div><div class="grid dashboard-tools">${toolCard('Study library','Documents, notes and source answers.','study','study')}${toolCard('Review cards',`${due.length} cards ready for recall.`,'cards','cards')}${toolCard('Focus session','Start a focused study session.','focus','clock')}${toolCard('Planner','Classes, deadlines and next steps.','planner','planner')}${toolCard('Grades','Marks, credits and progress.','grades','grade')}${toolCard('Writing','Citations and writing support.','writing','write')}${toolCard('Projects','Group work and milestones.','projects','people')}${toolCard('Subject tools','Calculators and study utilities.','tools','settings')}</div>${!state.courses.length?`<div class="dashboard-sample">${button('Explore fictional sample workspace','demo','','text-button')}</div>`:''}`;}

let studyCourse='',studyKeys=null;let handCurrent=null;
function handNote(){return state.handwriting.find(n=>n.id===handCurrent);}
function handwriting(){return heading('WRITE IT YOUR WAY','Handwriting notebook.','Pen, highlighter and sketches. Saved privately on your device, with no internet needed.')+button('+ Handwritten note','newHandNote','','primary')+state.handwriting.map(n=>item(n.title||'Untitled note',courseName(n.course)+' · '+(n.strokes?.length||0)+' strokes','openHandNote',n.id,'write')).join('')+(state.handwriting.length?'':empty('Start a note, choose a pen and write with your finger or stylus.'));}
function handPage(){const n=handNote();if(!n)return handwriting();return `<div class="studio-note-head"><input id="handTitle" value="${esc(n.title)}" maxlength="150" aria-label="Note title"><select id="handCourse" aria-label="Course / subject">${courseOptions().map(([v,t])=>`<option value="${esc(v)}" ${n.course===v?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="studio-toolbar">${Handwriting.toolbar()}</div><div class="studio-paper-scroll"><canvas id="handCanvas" width="900" height="1200" aria-label="Writing canvas. Choose a writing, shape, text or selection tool from the toolbar."></canvas></div><p id="handStatus" class="small muted" role="status"></p><details class="studio-export"><summary>Page actions & export</summary><div class="row wrap">${button('Export PNG','exportHandNote','','primary')}${button('PDF / print','printHandNote')}${button('Edit reviewed text','editHandText')}${button('Clear page','clearHandNote','','text-button danger')}${button('Delete note','deleteHandNote','','text-button danger')}</div></details>`;}
function bindHandwriting(){const n=handNote();if(!n)return;Handwriting.mount(n,()=>queueSave());$('handTitle').oninput=e=>{n.title=e.target.value;queueSave();};$('handCourse').onchange=e=>{n.course=e.target.value;queueSave();};}
const cloudNames={google:'Google Drive',onedrive:'OneDrive',icloud:'iCloud Drive'};
function cloudFiles(){return heading('YOUR FILES, WITH YOU','Cloud files.','Bring selected files into your hub, or save a copy to a location you choose.')+`<p class="network-note">${connection.mode==='connected'?'Connected mode':'Offline mode'} · ${connection.available?'Internet available':'No internet detected'}. Imported copies stay on this device for offline use. There is no automatic sync or whole-account access.</p><div class="cloud-providers">${['google','onedrive'].map(key=>`<article class="card cloud-provider ${key}"><span class="pill">ANDROID FILE PICKER</span><h2>${cloudNames[key]}</h2><p class="muted">Install and sign in to the provider’s Android app. In the Files picker, open the menu and choose ${cloudNames[key]} if it is listed, then select a file or folder.</p><div class="row wrap">${button('Import file','cloudImport',key,'primary')}${button('Save a copy','cloudSave',key)}${button('Open website','cloudWebsite',key,'text-button')}</div><p class="muted small">Account visibility, file types and saving support depend on the installed provider and school permissions. If it is missing, download a copy using its app or website, then import the downloaded file. To upload, export locally and upload from its app or website.</p></article>`).join('')}<article class="card cloud-provider icloud"><span class="pill">MANUAL TRANSFER ON ANDROID</span><h2>Apple iCloud Drive</h2><p class="muted">This Android app has no native iCloud account connection. Use iCloud Drive in a supported browser or on an Apple device/computer to download a file, then transfer it to this device and import it. To save, export a local copy and upload it through iCloud Drive.</p><div class="row wrap">${button('Open iCloud website','cloudWebsite','icloud','primary')}${button('Import downloaded file','cloudLocalImport')}${button('Export for upload','cloudSave','icloud')}</div><p class="muted small">Apple may limit features on Android browsers. Use a supported computer or Apple device if Drive or file upload is unavailable. Sign in only on Apple’s website; your Apple password is never entered in Student Hub.</p></article></div><article class="card"><h2>What can I transfer?</h2><p class="muted">Import documents, PDFs, images, slides or an ICS calendar. Save editable Word lecture notes, handwritten PNG pages, original imported documents, an ICS timetable, or a passphrase-encrypted workspace backup.</p><p class="muted small">Backups include text records and handwriting strokes, but exclude original document attachments and recordings. Export those separately. Cloud copies of Word, PNG, ICS and original documents use the cloud provider’s protection; only the workspace backup has the app’s passphrase encryption.</p>${button('Import from this device','cloudLocalImport')}${button('Backups & recordings guide','help')}</article>`;}
function cloudImport(provider,local=false){if(!local)requireConnected();editForm(local?'Import downloaded / on-device file':'Import using '+cloudNames[provider],[selectField('kind','What are you importing?',[['document','Document / PDF / image / slides'],['calendar','Calendar (.ics)']],'document'),selectField('course','Course / subject for documents',courseOptions())],async d=>{if(!local&&!await confirmation('Choose a cloud file?',`Android Files will open. Choose ${cloudNames[provider]} from its menu if available. The provider handles sign-in and download. This imports a separate editable/local copy; changes are not synced back.`,'Choose file'))return;await call('file.import',{kind:d.kind,id:Student.id(),course:d.course,cloud:!local,confirmed:!local,localOnly:local});},local?'Choose Downloads or an on-device folder. Cloud websites and downloads may need a connection.':'This opens the Android Files picker, not a direct account connection. If your provider is missing, cancel and use its app or website to download locally first.');}
function cloudSave(provider){const local=provider==='icloud';if(!local)requireConnected();const options=[['calendar','Timetable — ICS'],['backup','Workspace — encrypted backup'],...state.lectures.map(n=>['lecture:'+n.id,'Lecture notes — '+n.title]),...state.handwriting.map(n=>['handwriting:'+n.id,'Handwritten PNG — '+n.title]),...state.documents.map(n=>['document:'+n.id,'Original document — '+n.title])];editForm(local?'Export a copy for iCloud upload':'Save a copy using '+cloudNames[provider],[selectField('target','Choose what to save',options,'calendar'),field('password','Backup passphrase (only for workspace backup; 12+ characters)','password','')],async d=>{const label=local?'Export local copy':'Choose save location';if(!await confirmation(label,local?'Choose Downloads or an on-device folder, then upload the exported copy through iCloud Drive on a supported browser/device.':'Android Files will open. Choose '+cloudNames[provider]+' and your destination folder if listed. This creates a separate copy; later edits are not automatically uploaded.','Continue'))return;await persist();const flags={cloud:!local,confirmed:!local,localOnly:local};const [kind,id]=d.target.split(':');if(kind==='backup'){if(d.password.length<12)throw Error('Use a backup passphrase of at least 12 characters.');await call('backup.export',{password:d.password,...flags});}else if(kind==='calendar'){await call('file.export',{title:'Timetable',name:'Student-Hub-Timetable',text:Student.calendar(state.events),format:'ics',...flags});}else if(kind==='document'){await call('document.export',{id,...flags});}else if(kind==='lecture'){const n=state.lectures.find(n=>n.id===id);if(!n?.notes?.trim())throw Error('Create or enter lecture notes before exporting them.');await call('file.export',{title:n.title,name:n.title,text:n.notes,format:'docx',...flags});}else if(kind==='handwriting'){const n=state.handwriting.find(n=>n.id===id);if(!n)throw Error('This handwritten note is unavailable.');await call('file.exportImage',{name:n.title,image:Handwriting.png(n),...flags});}},local?'Manual upload: this exports a local file. iCloud upload takes place separately outside this app.':'In Android Files, select your provider and destination. Only services shown by Android can be used here; otherwise export locally and upload with the provider app.');}
function measureQuickAccess(){const height=$('quickAccess')?.getBoundingClientRect().height;if(height>0)document.documentElement.style.setProperty('--quick-height',Math.ceil(height)+'px');}
function setTextSize(value){state.profile.fontSize=Student.textSize(value);applyPreferences();if($('fontRange'))$('fontRange').value=state.profile.fontSize;if($('fontValue'))$('fontValue').textContent=state.profile.fontSize+' px';queueSave();measureQuickAccess();}
function appearancePanel(){return `<article class="card" id="appearancePanel"><h2>${icon('settings')} Display & accessibility</h2><p class="muted small">Choose a comfortable reading size. Your choice is saved on this device.</p><label for="fontRange">Text size · <output id="fontValue">${Student.textSize(state.profile.fontSize)} px</output></label><div class="font-controls"><button data-action="fontSmaller" class="secondary" aria-label="Decrease text size">A−</button><input id="fontRange" type="range" min="14" max="24" step="1" value="${Student.textSize(state.profile.fontSize)}" aria-label="Text size"><button data-action="fontLarger" class="secondary" aria-label="Increase text size">A+</button></div><div class="row wrap">${button('Standard','fontPreset','16')}${button('Large','fontPreset','20')}${button('Extra large','fontPreset','24')}${button('Light / dark','theme')}${button('Favorite shortcuts','manageFavorites')}</div><hr><h3>Reset appearance & shortcuts</h3><p class="muted small">Restore standard text, light theme and the four default shortcuts. Notes, courses, recordings, accounts, connection settings and backups are kept.</p>${button('Reset appearance & shortcuts','resetAppearance','','secondary')}</article>`;}
const quickTools={accounts:['Accounts','people'],home:['Today','home'],courses:['Courses','courses'],planner:['Planner','planner'],study:['Study','study'],handwriting:['Write','write'],cloudFiles:['Cloud','courses'],grades:['Grades','grade'],focus:['Focus','clock'],writing:['Writing','write'],budget:['Budget','money'],projects:['Projects','people'],career:['Career','career'],contacts:['Contacts','people'],tools:['Tools','grade'],settings:['Settings','settings'],help:['Guide','study'],more:['All tools','more']};
function renderQuickAccess(){const chosen=Student.favorites(state.profile.favorites);$('bottom').innerHTML=chosen.map((key,i)=>{const [label,symbol]=quickTools[key],active=view===key||key==='study'&&view==='lecture'||key==='handwriting'&&view==='handPage';return `<button data-action="quickNav" data-id="${key}" class="quick-link tone-${i} ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></button>`;}).join('')+`<button class="quick-customize" data-action="manageFavorites" aria-label="Customize favorite shortcuts"><span aria-hidden="true">☆</span><span>${chosen.length?'Favorites':'Add favorites'}</span></button>`;document.querySelectorAll('#sidebar [data-action="drawerNav"]').forEach(b=>{if(!b.querySelector('svg')){const label=b.textContent.replace('›','').trim();b.innerHTML=icon(quickTools[b.dataset.id]?.[1]||'study')+'<span class="drawer-label">'+esc(label)+'</span><span aria-hidden="true">›</span>';}let star=b.parentElement.classList.contains('drawer-tool-row')?b.parentElement.querySelector('.favorite-star'):null;if(!star){const row=document.createElement('div');row.className='drawer-tool-row';b.before(row);row.append(b);star=document.createElement('button');star.className='favorite-star';star.dataset.action='toggleFavorite';star.dataset.id=b.dataset.id;row.append(star);}const selected=chosen.includes(b.dataset.id);star.textContent=selected?'★':'☆';star.setAttribute('aria-pressed',String(selected));star.setAttribute('aria-label',(selected?'Remove ':'Add ')+(quickTools[b.dataset.id]?.[0]||'tool')+(selected?' from favorites':' to favorites'));});requestAnimationFrame(measureQuickAccess);}
function favoriteManager(){const chosen=Student.favorites(state.profile.favorites);showReader('Your favorite shortcuts',`<p class="muted">Choose up to six tools for the fixed bottom bar. Remove one to make room; use arrows to change their order. Saved to your local profile.</p><p id="favoriteNotice" class="small" role="status"></p><div class="favorite-current">${chosen.map((key,i)=>`<div class="favorite-row"><strong>${esc(quickTools[key][0])}</strong><button data-action="moveFavorite" data-id="${key}:up" aria-label="Move ${quickTools[key][0]} earlier" ${i===0?'disabled':''}>↑</button><button data-action="moveFavorite" data-id="${key}:down" aria-label="Move ${quickTools[key][0]} later" ${i===chosen.length-1?'disabled':''}>↓</button></div>`).join('')||'<p>No favorites selected yet.</p>'}</div><div class="favorite-options">${Object.entries(quickTools).map(([key,[label]])=>`<button data-action="toggleFavorite" data-id="${key}" aria-pressed="${chosen.includes(key)}" class="favorite-option ${chosen.includes(key)?'selected':''}"><span>${chosen.includes(key)?'★':'☆'}</span>${esc(label)}</button>`).join('')}</div>`,button('Done','closeFavorites','','primary'));}
function toolCard(title,desc,action,symbol='study'){if(action==='career'&&state.profile.mode==='school')return '';return `<button class="tool" data-action="${action}">${icon(symbol)}<strong>${title}</strong><small>${desc}</small></button>`;}
function courses(){return heading(state.profile.mode==='school'?'YOUR SCHOOL TERM':'YOUR SEMESTER','Room to grow.','Keep every subject, teacher and room together.')+button(state.profile.mode==='school'?'+ Add subject':'+ Add course','addCourse','','primary')+state.courses.map(c=>`<article class="card"><div class="section-title"><span class="pill">${esc(c.code||'COURSE')}</span>${button('Edit','editCourse',c.id,'text-button')}</div><h2>${esc(c.name)}</h2><p class="muted small">${esc(c.teacher||'Teacher not set')} · ${esc(c.room||'Room not set')}<br><span class="university-feature">${Number(c.credits)||0} credits · </span>${state.lectures.filter(l=>l.course===c.id).length} lectures</p><div class="row wrap">${button('New lecture','courseLecture',c.id,'primary')}${button('Assignment','courseTask',c.id)}${button('Delete','deleteCourse',c.id,'text-button danger')}</div></article>`).join('')+(state.courses.length?'':empty('Add courses for this semester.<br>Lectures, deadlines and grades can then be linked to them.'));}
function planner(){const tasks=state.tasks.filter(t=>tab==='done'?t.status==='done':t.status!=='done').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'));const events=[...state.events].sort((a,b)=>a.start.localeCompare(b.start));return heading('TIME FOR WHAT MATTERS','Your planner.','Classes, deadlines and manageable next steps.')+`<div class="row wrap">${button('+ Assignment','addTask','','primary')}${button('+ Class / event','addEvent')}${button('Plan my week','studyPlan')}</div><div class="tabs">${['tasks','calendar','done'].map(t=>button(t==='tasks'?'Open work':t==='calendar'?'Timetable':'Completed','plannerTab',t,t===tab?'active':'')).join('')}</div>`+(tab==='calendar'?`${events.map(e=>item(e.title,(e.allDay?new Date(e.start).toLocaleDateString()+' · All day':new Date(e.start).toLocaleString())+' · '+(e.location||'No location'),'eventDetail',e.id,'planner')).join('')||empty('Add classes, exams or office hours.')}<div class="row wrap">${button('Export calendar','exportCalendar')}${button('Import .ics file','importCalendar')}</div>`:tasks.map(t=>`<article class="card"><div class="section-title"><span class="pill">${esc(t.type||'TASK')}</span><span class="tag">${esc(t.priority||'normal')}</span></div><h3>${esc(t.title)}</h3><p class="muted small">${esc(courseName(t.course))} · ${esc(t.due||'No deadline')} · ${Number(t.minutes)||0} estimated minutes</p><div class="mini-actions">${button(t.status==='done'?'Reopen':'Mark done','toggleTask',t.id,'text-button')}${button('Details','taskDetail',t.id,'text-button')}${button('Edit','editTask',t.id,'text-button')}</div></article>`).join('')||empty('Nothing in this list.<br>Add a task or change the view.'))+`<p class="muted small">Local notification times are approximate. Enable reminders in Settings; Android battery settings can affect delivery.</p>`;}
function study(){return heading('MAKE IT YOURS','Your study space.','Capture, organise and remember.')+`<div class="tabs">${[['library','Study library'],['lectures','Lectures'],['documents','Documents'],['cards','Flashcards'],['search','Search materials']].map(([k,n])=>button(n,'studyTab',k,tab===k?'active':'')).join('')}</div>`+(tab==='library'?studyLibrary():tab==='documents'?`${button('+ Import document','importDocument','','primary')}<p class="muted small">TXT, MD, DOCX, PPTX and readable PDF text are imported locally. Scanned PDFs and images support free offline OCR, one page at a time. Review handwriting, page order, numbers and equations. Legacy DOC/PPT, protected files and complex layouts may need conversion or manual text.</p>${state.documents.map(d=>item(d.title,courseName(d.course)+' · '+d.type,'document',d.id,'study')).join('')||empty('Your course material, ready to carry.<br>Import a document from this device.')}`:tab==='cards'?cards():tab==='search'?`<div class="row"><input id="materialQuery" aria-label="Search your materials" placeholder="Ask a question or enter a topic…">${button(icon('search'),'searchMaterials','','primary')}</div><p class="muted small">Quick source answers retrieve original passages. Answer on this device uses the prepared local model with selected excerpts. Nothing is uploaded; optional cloud services are separate.</p>${button('Answer on this device · free','localTutor','','primary')}${button('Quick source answer','quickAnswer')}<div id="materialResults"></div>`:`<div class="row wrap">${button('+ New lecture','newLecture','','primary')}${button('Import text / slides','importDocument')}</div>${state.lectures.map(l=>item(l.title,courseName(l.course)+' · '+l.date,'lecture',l.id,'mic')).join('')||empty('Start with a lecture.<br>Record, paste text, or import a document.')}`);}
function cards(){const due=state.cards.filter(c=>c.due<=Student.day());const list=due.length?due:state.cards;if(cardIndex>=list.length)cardIndex=0;const c=list[cardIndex];return `<div class="row wrap">${button('+ Create card','addCard','','primary')}${button('Practice quiz','startQuiz')}${button('Export cards','exportCards')}</div><p class="muted small">${due.length} due · ${state.cards.length} saved · ${due.length?'Review queue':'Browsing all cards'}</p>`+(c?`<div class="flashcard"><span class="eyebrow">${esc(courseName(c.course))}</span><p class="${flipped?'answer':'question'}">${esc(flipped?c.back:c.front)}</p>${button(flipped?'Show question':'Reveal answer','flipCard','','text-button')}<span class="source">Source: ${esc(c.source||'Your card')}</span></div><div class="row wrap">${button('Again today','reviewAgain',c.id)}${button('I remembered','reviewKnown',c.id,'primary')}${button('Edit','editCard',c.id,'text-button')}${button('Delete','deleteCard',c.id,'text-button danger')}</div>`:empty('Create a card, or generate editable cards<br>from definition sentences in a lecture.'));}
function more(){return heading('YOUR STUDENT HUB','More room to thrive.','The practical side of student life, together.')+`<div class="grid">${toolCard('Cloud files','Import and save with Drive, OneDrive or manual iCloud transfer.','cloudFiles','courses')}${toolCard('Handwriting notebook','Write and sketch with offline drawing tools.','handwriting','write')}${toolCard('Grades & GPA','See your progress and target marks.','grades','grade')}${toolCard('Focus & wellbeing','A calmer rhythm for studying.','focus','clock')}${toolCard('Writing & citations','Build an outline and manage sources.','writing','write')}${toolCard('Student budget','Know what comes in and goes out.','budget','money')}${toolCard('Group projects','Tasks, roles and local meeting notes.','projects','people')}${toolCard('Career & opportunities','Applications, résumés and deadlines.','career','career')}${toolCard('Campus & contacts','Your own useful local directory.','contacts','courses')}${toolCard('Subject tools','Quadratics and unit conversions.','tools','grade')}${toolCard('Settings & backup','Your profile, access and data.','settings','settings')}${toolCard('Guide & capabilities','What works offline in version one.','help','study')}</div>`;}
function grades(){const rows=state.courses.map(c=>{let g;try{g=Student.grade(state.grades.filter(r=>r.course===c.id));}catch{g={current:null,weight:0,earned:0};}return `<article class="card"><h3>${esc(c.name)}</h3><div class="metrics"><div><b>${g.current==null?'—':g.current.toFixed(1)+'%'}</b><span>Assessed work</span></div><div><b>${g.weight.toFixed(0)}%</b><span>Course weight graded</span></div></div>${button('Assessments / target','courseGrades',c.id,'secondary')}</article>`;});const gpa=Student.gpa(state.courses);return heading('KNOW WHERE YOU STAND','Progress, made visible.','Weighted marks and targets, using the figures you enter.')+`<div class="row wrap">${button('+ Assessment','addGrade','','primary')}${button('Export grades','exportGrades')}</div>${rows.join('')||empty('Add a course to begin tracking grades.')}<article class="card university-feature"><h2>Credit-weighted GPA</h2><p class="muted small">Enter each completed course’s official GPA value and credits through Edit course. No percentage-to-GPA conversion is assumed.</p><h1>${gpa==null?'—':gpa.toFixed(2)}</h1><p class="muted small">Completed credits: ${state.courses.filter(c=>c.gpa!==''&&c.gpa!=null).reduce((n,c)=>n+Number(c.credits||0),0)} / ${state.profile.targetCredits||'target not set'}. Check institution-specific rules.</p></article>`;}
function budget(){const month=Student.day().slice(0,7),b=Student.budget(state.expenses,month);return heading('SMALL HABITS, MORE FREEDOM','Your student budget.',month)+`<div class="metrics"><div><b>$${b.income.toFixed(0)}</b><span>Income</span></div><div><b>$${b.expenses.toFixed(0)}</b><span>Expenses</span></div><div><b>$${(b.income-b.expenses).toFixed(0)}</b><span>Balance</span></div></div><div class="row wrap">${button('+ Entry','addExpense','','primary')}${button('Export CSV','exportExpenses')}</div>${state.expenses.slice().reverse().map(e=>item(`${e.type==='income'?'+':'−'}$${Number(e.amount).toFixed(2)} · ${e.title}`,e.date+' · '+e.category,'expenseDetail',e.id,'money')).join('')||empty('Track tuition, rent, food, transport,<br>scholarships and other student costs.')}<p class="muted small">Amounts use your entered currency labels; no exchange rates or financial advice are supplied.</p>`;}
function writing(){return heading('MAKE YOUR THINKING CLEAR','Writing & research.','Your argument, with room to develop.')+`<div class="grid">${toolCard('Essay outline','Turn your thesis and main points into an editable structure.','essay','write')}${toolCard('Message draft','Prepare an email to a teacher or adviser.','messageDraft','write')}</div><div class="section-title"><h2>References</h2>${button('+ Source','addCitation','','text-button')}</div>${state.citations.map(c=>item(c.title,Student.citation(c),'citationDetail',c.id,'study')).join('')||empty('Save a source with author, title, year and URL.<br>Always check the required citation style.')}<div class="row wrap">${button('Export bibliography','exportCitations')}${button('Research notes','researchNote')}</div>`;}
function career(){return heading('YOUR NEXT CHAPTER','Possibilities, organised.','Keep applications, opportunities and career notes together.')+`<div class="row wrap">${button('+ Application / opportunity','addCareer','','primary')}${button('Résumé template','resume')}</div>${state.career.map(c=>item(c.title,c.organization+' · '+c.status+' · '+(c.due||'No deadline'),'careerDetail',c.id,'career')).join('')||empty('Add a co-op, internship, scholarship,<br>job application or portfolio milestone.')}`;}
function projects(){return heading('GOOD WORK, TOGETHER','Group projects.','A local project board. Sharing is by exported file in this version.')+button('+ Project','addProject','','primary')+state.projects.map(p=>item(p.title,p.team||'Add your team members','projectDetail',p.id,'people')).join('')+(state.projects.length?'':empty('Keep team roles, meeting notes and next actions<br>in one place on this device.'));}
function contacts(){return heading('KNOW WHERE TO GO','Your campus directory.','Save the people, places and services you use.')+button('+ Contact / location','addContact','','primary')+state.contacts.map(c=>item(c.name,c.role+' · '+c.location,'contactDetail',c.id,'people')).join('')+(state.contacts.length?'':empty('Add library hours, teachers, advisers,<br>student services, transport notes or clubs.'));}
function focus(){const total=state.focus.filter(f=>f.date===Student.day()).reduce((n,f)=>n+Number(f.minutes),0);return heading('ONE THING AT A TIME','Find your focus.','A little space for work, and a little space for you.')+`<article class="card"><div class="section-title"><span class="eyebrow">FOCUS SESSION</span><span class="pill">${total} MIN TODAY</span></div><div id="focusClock" class="focus-clock">25:00</div><label>Session length<select id="focusMinutes"><option value="25">25 minutes</option><option value="45">45 minutes</option><option value="5">5-minute break</option><option value="15">15 minutes</option></select></label><div class="row wrap">${button('Start session','startFocus','','primary')}${button('Stop session','stopFocus')}</div><p class="muted small">The timer uses elapsed clock time. It resumes display when you reopen the app. Notifications are optional; timing is not an attention measurement.</p></article><div class="row wrap">${button('Daily check-in','checkIn')}${button('View check-ins','viewJournal')}</div><p class="muted small">Wellbeing notes are a personal journal, not a health assessment.</p>`;}
function tools(){return heading('A SMALL STUDY TOOLKIT','Work it through.','Check the method, not just the result.')+`<article class="card"><h2>Quadratic equation</h2><p class="muted">ax² + bx + c = 0</p><div class="two"><label>a<input id="qa" type="number" value="1" step="any"></label><label>b<input id="qb" type="number" value="-6" step="any"></label><label>c<input id="qc" type="number" value="5" step="any"></label></div>${button('Show roots & vertex','quadratic','','primary')}<div id="mathResult"></div></article><article class="card"><h2>Unit conversion</h2><label>Conversion<select id="unit"><option value="mft">Metres → feet</option><option value="ftm">Feet → metres</option><option value="kglb">Kilograms → pounds</option><option value="lbkg">Pounds → kilograms</option><option value="cf">Celsius → Fahrenheit</option><option value="fc">Fahrenheit → Celsius</option></select></label><label>Value<input id="unitValue" type="number" step="any" value="1"></label>${button('Convert','convert','','primary')}<p id="unitResult"></p></article>`;}
function loginTime(timestamp,fallback,empty){const value=Number(timestamp)>0?Number(timestamp):fallback;if(!value)return empty;const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):String(fallback||empty);}
function loginDetails(){return `<div id="accountDetails" class="account-details"><span class="pill">SIGNED IN ON THIS DEVICE</span><dl><dt>Student</dt><dd>${esc(account.displayName||account.username)}</dd><dt>Username</dt><dd>@${esc(account.username)}</dd><dt>Current login</dt><dd>${esc(loginTime(account.lastLoginAt,account.lastLogin,'Not recorded for this session'))}</dd><dt>Previous login</dt><dd>${esc(loginTime(account.previousLoginAt,account.previousLogin,'First login — no previous sign-in'))}</dd></dl><p class="muted small">Times use this device’s timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone||'device local time')}. Login details refer to this local Student Hub account.</p></div>`;}
function settings(){return heading('BUILT AROUND YOU','Your workspace.','Local by design. Yours to organise.')+`<article class="card"><h2>${esc(account.displayName||account.username)}</h2>${loginDetails()}<div class="row wrap">${button('Edit student profile','profile','','primary')}${button('Choose plan','changePlan')}${button('Cloud files','cloudFiles')}${button('Customize favorites','manageFavorites')}</div><p class="muted small">${esc(state.profile.institution||'Institution not set')} · ${esc(state.profile.mode)}<br>${esc(state.profile.program||'Program / grade not set')} · ${esc(state.profile.semester||'Semester not set')}</p></article>${appearancePanel()}<article class="card"><h2>Free local study tools</h2><p class="muted">Document answers, prepared local Qwen AI, notes, source quizzes and offline OCR need no API key, credits or AI account. The local model uses device memory and storage; review generated drafts against their source excerpts.</p>${button('Email & calendars','accounts')}</article><article class="card"><h2>Optional cloud services</h2><p class="muted small">Mode: ${esc(connection.mode||'offline')} · Network: ${connection.available?'available':'unavailable'} · AI key: ${connection.hasApiKey?'saved':'not saved'}</p><p class="muted small">Local study tools work in either mode. Optional cloud translation, online audio/page services, websites and Canvas imports require provider configuration and confirmation.</p><div class="row wrap">${button('Run local self-test','selftest','','primary')}${button('Enable reminders','enableReminders')}${button('Offline / Connected services','connectionSettings')}</div><pre id="testResult"></pre><div class="row wrap">${button('Check AI model','onlineCheck')}${button('Remove AI key','clearOnlineKey','','text-button danger')}${button('Import Canvas courses','canvasCourses')}${button('Import Canvas assignments','canvasAssignments')}${button('Import calendar feed','onlineCalendar')}</div></article><article class="card"><h2>Backup & restore</h2><p class="muted small">Passphrase-encrypted backup of workspace text, notes and records. Original document attachments and audio are excluded; export those separately. Use an on-device file location to remain offline.</p><label>Backup passphrase<input id="backupPassword" type="password" minlength="12" autocomplete="new-password"></label><div class="row wrap">${button('Export encrypted backup','backup')}${button('Restore backup','restore')}</div></article><article class="card"><h2>Recent activity</h2>${state.activity.slice(0,15).map(a=>`<p class="small">${esc(a.action)}<br><span class="muted small">${new Date(a.at).toLocaleString()}</span></p>`).join('')||'<p class="muted small">Your study actions appear here.</p>'}</article><p class="muted small">Velthon Student Hub 0.2.0<br>Developed and designed by VELTHON Design and Development<br>First test release · physical-device validation pending.</p>`;}
function help(){return heading('A LITTLE GUIDANCE','Study without AI credits.','Your core study tools work locally, without an AI account.')+`<article class="card"><h2>Start with your material</h2><p class="muted">Upload a book or document, record a lecture, or add handwriting. Review extracted text, then choose your sources in Study library. Ask a question, build source cards or practise a quiz.</p>${button('Open study library','nav','study','primary')}${button('Load fictional sample workspace','demo')}</article><article class="card"><h2>Free on this device</h2><p class="muted">Quick source answers, bundled local Qwen drafts, notes, OCR, handwriting review, source quizzes and automatic initial English/French/Spanish speech detection need no API key. Generated answers are drafts; verify against the displayed source passages.</p><p class="muted">Printed text and neat handwriting may be recognized offline. Cursive, equations, complex layouts and speech in noise require review. Nearby voices are not reliably removed. Long recordings should be split into parts.</p></article><article class="card"><h2>Accounts and optional online tools</h2><p class="muted">Device calendar access is read-only and requires permission. The operating system syncs your email calendar. Cloud files use the signed-in Android file provider. This does not grant inbox access or an AI subscription.</p>${button('Email & calendars','accounts')}${button('Cloud files','cloudFiles')}<p class="muted">Optional cloud translation and audio/page services need their own credentials and may have provider charges. They are not required for the free local study workflow.</p></article><article class="card"><h2>Keep your work</h2><p class="muted">Export a passphrase-encrypted workspace backup. Original attachments and recordings are excluded, so export those separately. Reset appearance changes only display and shortcuts, keeping study data.</p>${button('Settings & backup','settings')}</article>`;}

function courseOptions(){return [['','Unassigned'],...state.courses.map(c=>[c.id,c.name])];}
function selectField(key,label,options,value=''){return {key,label,type:'select',options,value};}
function field(key,label,type='text',value='',required=false){return {key,label,type,value,required};}
const connectionOptions=[['offline','Offline','Prepared local tools work here. First use of engines/libraries needs a connection.','offline'],['connected','Connected','Prepare free engines and open selected cloud files. Material stays in this browser.','connected']];
const educationOptions=[['school','School','School subjects, homework, tests and grade-level planning.','school'],['university','University / College','Courses, lectures, credits, assignments and campus planning.','university']];
function choiceField(key,label,options,value){return {key,label,type:'choice',options,value};}
function choiceMarkup(f){return `<fieldset class="choice-field"><legend>${esc(f.label)}</legend><input type="hidden" id="f-${f.key}" value="${esc(f.value)}"><div class="choice-grid">${f.options.map(([value,title,description,tone])=>`<label class="choice-option ${tone}"><input type="radio" name="choice-${f.key}" value="${value}" ${f.value===value?'checked':''} data-choice-key="${f.key}"><span class="choice-content"><strong>${title}</strong><span>${description}</span><b class="selection-label">${f.value===value?'✓ Selected':'Select'}</b></span></label>`).join('')}</div></fieldset>`;}
function renderModePanel(){$('sidebarModes').innerHTML=workspaceChoices()+`<label>Interface language<select id="uiLanguage"><option value="en">English</option><option value="fr">Français</option><option value="es">Español</option></select></label>`;$('uiLanguage').value=state.profile.uiLanguage||'en';$('uiLanguage').onchange=async e=>{state.profile.uiLanguage=e.target.value;await persist();I18n.set(e.target.value);renderIfNeeded();renderModePanel();};if(window.I18n)I18n.apply();}
function accounts(){return heading('YOUR DEVICE ACCOUNTS','Email & calendars.','Use calendar accounts already signed in on your phone.')+`<article class="card"><h2>Connect through Android</h2><p class="muted">Add or sign in to Google, Outlook or a supported school account in Android Settings. Calendar sync must be enabled there. Student Hub can read selected calendars after permission; it does not read your email inbox or obtain an AI subscription.</p>${button('Open device account settings','deviceAccounts','','primary')}${button('Choose device calendars','chooseCalendars')}<p class="muted small">Cloud documents use the signed-in provider in Android Files. If a provider is absent, download locally then import.</p>${button('Cloud files & storage','cloudFiles')}</article><article class="card"><h2>Automatic calendar refresh</h2><p class="muted">${state.profile.calendarAuto?'Enabled':'Off'}. Selected calendar entries are read from the device on sign-in and every five minutes while this app is open. The operating system handles the email account’s online sync.</p>${button(state.profile.calendarAuto?'Disable auto refresh':'Enable auto refresh','calendarAuto')}${button('Refresh calendar now','calendarRefresh')}<p class="muted small">Imports the previous 30 and next 180 days, up to 1,000 events. Existing event copies are updated; removals are reflected within this window. Local events are kept.</p><p id="calendarStatus" class="small"></p></article>`;}
function calendarInstant(value,allDay){const date=new Date(value);return allDay?new Date(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()).toISOString():date.toISOString();}
async function syncDeviceCalendars(){const ids=state.profile.calendarIds||[];if(!ids.length)throw Error('Choose at least one device calendar first.');const rows=await call('calendar.events',{ids});const remote=rows.map(e=>({id:'device-'+e.key,source:'device-calendar',calendarId:e.calendarId,title:e.title||'Calendar event',start:calendarInstant(e.start,e.allDay),end:calendarInstant(e.end,e.allDay),allDay:!!e.allDay,location:e.location||'',course:'',notes:'Imported from a selected device calendar.'}));const chosen=new Set(ids.map(String));state.events=state.events.filter(e=>e.source!=='device-calendar'||!chosen.has(String(e.calendarId)));state.events.push(...remote);await persist();if($('calendarStatus'))$('calendarStatus').textContent=rows.length+' calendar events refreshed.';}
setInterval(()=>{if(account&&state.profile.calendarAuto&&!document.hidden)syncDeviceCalendars().catch(()=>{});},300000);
function studyLibrary(){const bundle=Student.bundle(state,studyCourse,studyKeys);return `<article class="card"><h2>One library. All your learning.</h2><p class="muted">Use textbooks, Word/PDF/text files, lecture notes and reviewed handwriting together. Local answers and quizzes are free; no AI key is needed.</p><label>Course / subject<select id="studyCourse">${courseOptions().map(([id,title])=>`<option value="${esc(id)}" ${studyCourse===id?'selected':''}>${esc(id?title:'All courses')}</option>`).join('')}</select></label><div class="row wrap">${button('Upload book / material','importDocument','','primary')}${button('Record lecture','newLecture')}${button('Handwritten note','handwriting')}</div></article><article class="card"><h2>Choose study sources</h2>${Student.sources(state,studyCourse).map(x=>`<label class="check"><input type="checkbox" data-study-source="${esc(x.key)}" ${!studyKeys||studyKeys.includes(x.key)?'checked':''}><span><strong data-no-translate>${esc(x.title)}</strong><br>${esc(x.kind)} · ${x.text.trim()?'Ready to study':'Needs text / OCR review'}</span></label>`).join('')||empty('Upload a book or record your first lecture.')}<p class="muted small">${bundle.readable.length} readable sources · ${bundle.needsText.length} need text. Use offline OCR for scans/images and review handwriting recognition before studying.</p><div class="row wrap">${button('Build study structure','bundleStructure','','primary')}${button('Create source cards','bundleCards')}${button('Quiz selected sources','bundleQuiz')}${button('Study help','bundleHelp')}</div></article><article class="card"><h2>Suggested topics</h2>${bundle.topics.slice(0,12).map(t=>`<p data-no-translate>${esc(t.title)}<br><small>${esc(t.source)}</small></p>`).join('')||'<p class="muted">Topics appear when clear definitions are present. You can always ask questions and search readable passages.</p>'}</article>`;}
function bindLibrary(){$('studyCourse').onchange=e=>{studyCourse=e.target.value;studyKeys=null;render();};document.querySelectorAll('[data-study-source]').forEach(el=>el.onchange=()=>{studyKeys=[...document.querySelectorAll('[data-study-source]:checked')].map(n=>n.dataset.studySource);});}
function answerSources(answer){return answer.passages.map((p,i)=>`<article class="card"><strong data-no-translate>[S${i+1}] ${esc(p.title)} · passage ${p.index}</strong><p class="quote">${esc(p.quote)}</p>${button('Open source',p.kind==='lecture'?'lecture':p.kind==='handwriting'?'openHandNote':'document',p.id)}</article>`).join('');}
function workspaceChoices(){return `<section class="workspace-choices" aria-label="Workspace modes"><h2>Make this hub yours</h2><p class="muted small">Choose your connection and education separately. Change either at any time.</p><h3>Connection mode</h3><div class="choice-grid">${connectionOptions.map(([value,title,description,tone])=>`<button class="mode-block ${tone}" data-action="chooseConnection" data-id="${value}" aria-pressed="${connection.mode===value}"><strong>${title}</strong><span>${description}</span><b>${connection.mode===value?'✓ Selected':'Select'}</b></button>`).join('')}</div><p class="network-note">${connection.available?'Internet available on this device.':'No internet detected. Local tools remain available.'} ${connection.mode==='offline'?'Online services are off.':'Online requests need internet; nothing uploads automatically.'}</p><h3>Education mode</h3><div class="choice-grid">${educationOptions.map(([value,title,description,tone])=>`<button class="mode-block ${tone}" data-action="chooseEducation" data-id="${value}" aria-pressed="${state.profile.mode===value}"><strong>${title}</strong><span>${description}</span><b>${state.profile.mode===value?'✓ Selected':'Select'}</b></button>`).join('')}</div><p class="muted small">Both education modes include all tools. This sets your workspace context; existing notes and courses stay available.</p></section>`;}
function updateWorkspaceStatus(){document.body.classList.toggle('school-mode',state.profile.mode==='school');document.querySelectorAll('#sidebar [data-action="drawerNav"]').forEach(b=>{const row=b.closest('.drawer-tool-row')||b;row.hidden=state.profile.mode==='school'&&b.dataset.id==='career';});if($('signedInUser'))$('signedInUser').textContent=account?'Signed in: '+(account.displayName||account.username):'';const el=$('workspaceStatus');if(el)el.textContent=(state.profile.mode==='school'?'School':'University / College')+' workspace';const label=$('sidebarContext');if(label)label.textContent=(state.profile.mode==='school'?'School':'University / College')+' · '+(connection.mode==='connected'?'Connected':'Offline');}
