function renderIfNeeded(){if(view!=='lecture')render();}
function put(collection,data,existing){if(existing)Object.assign(existing,data);else state[collection].push({id:Student.id(),...data});audit(existing?'Updated '+collection:'Added '+collection);}
function showReader(title,body,actions=''){$('readerTitle').textContent=title;$('readerBody').innerHTML=body;$('readerActions').innerHTML=actions;if(!$('reader').open)$('reader').showModal();}
function textReader(title,text,actions=''){showReader(title,'<pre>'+esc(text)+'</pre>',actions);}
async function exportText(title,text,format='txt'){await call('file.export',{name:'Student-Hub-'+title,title,text,format});}
