function recordUi(){ $('micDevice').disabled=!!recording;$('micSensitivity').disabled=!!recording;$('micDirection').disabled=true;$('transcript').readOnly=!!recording;for(const k of ['record','play','deleteAudio','importAudio','retryAudio','deleteLecture','exportAudio','transcribeOnline','onlineNotes','translateNotes'])$(k).disabled=k==='record'?!!recording:!!recording;$('stop').disabled=!recording;$('pause').disabled=!recording;$('pause').textContent=paused?'Resume':'Pause';$('recState').textContent=recording?(paused?'Paused':'Recording'):'Ready';$('soundBars').classList.toggle('active',!!recording);$('soundBars').classList.toggle('paused',paused);}
