async function viewDocument(id){const d=state.documents.find(x=>x.id===id);if(!d)return;docPage=0;let body=d.text?'<pre>'+esc(d.text)+'</pre>':'<p class="muted">Loading local preview…</p>';showReader(d.title,body,button('Add / edit text','documentText',id)+button('Create study note','documentNote',id)+button('Export original','documentExport',id)+button('Delete','documentDelete',id,'text-button danger')+(['pdf','image'].includes(d.type)?button('Extract text · offline / free','documentOcr',id)+button('Cloud extraction · optional','onlineImageText',id):''));if(['pdf','image'].includes(d.type))await renderPage(d,0);else if(!d.text)$('readerBody').innerHTML='<p>No text extraction is available for this attachment. Export the original to open it in another app.</p>';}
async function renderPage(d,page){const data=await call('document.page',{id:d.id,page});docPage=data.page;$('readerBody').innerHTML=`<img src="${data.image}" alt="Local document page ${data.page+1}"><p class="muted small">Page ${data.page+1} of ${data.pages}. Add reviewed text to use this material for notes and flashcards.</p>`;if(data.pages>1)$('readerBody').innerHTML+=button('Previous page','docPrev',d.id)+button('Next page','docNext',d.id);$('readerBody').dataset.pages=data.pages;}
function startQuiz(){if(state.cards.length<2){notify('Create at least two study cards for a practice quiz.',true);return;}quiz={cards:[...state.cards].sort(()=>Math.random()-.5).slice(0,10),index:0,score:0,answered:false};renderQuiz();}
function renderQuiz(){if(!quiz)return;if(quiz.index>=quiz.cards.length){state.quizRuns.push({id:Student.id(),at:Student.now(),score:quiz.score,total:quiz.cards.length});audit('Completed practice quiz');textReader('Practice complete',`You answered ${quiz.score} of ${quiz.cards.length} correctly.\n\nReview the source material behind any missed answers. These are practice cards, not a validated exam.`,button('Review cards','cards'));quiz=null;return;}const c=quiz.cards[quiz.index],others=(quiz.pool||state.cards).filter(x=>x.id!==c.id&&x.back!==c.back).sort(()=>Math.random()-.5).slice(0,3);quiz.options=[c.back,...others.map(x=>x.back)].sort(()=>Math.random()-.5);showReader(`Question ${quiz.index+1} of ${quiz.cards.length}`,`<h2>${esc(c.front)}</h2>${quiz.options.map((o,i)=>`<button class="answer-choice" data-action="quizAnswer" data-id="${i}">${esc(o)}</button>`).join('')}<div id="quizFeedback"></div>`);}
function bindPage(){if(view==='study'&&tab==='library')bindLibrary();if(view==='settings'&&$('fontRange'))$('fontRange').oninput=e=>setTextSize(e.target.value);if(view==='handPage')bindHandwriting();if(view==='focus')updateFocus();if(window.I18n)I18n.apply();}
function updateFocus(){const clock=$('focusClock');if(!clock)return;const session=state.profile.focusSession;const remaining=session?Math.max(0,Math.ceil((session.end-Date.now())/1000)):25*60;clock.textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');}
setInterval(()=>{const session=state.profile.focusSession;if(session&&session.end<=Date.now()){state.focus.push({date:Student.day(),minutes:session.minutes,completed:true});delete state.profile.focusSession;queueSave();notify('Session complete. Take a moment to stretch and reset.');}updateFocus();},1000);
async function syncReminders(){if(!state.profile.notifications)return;const items=[];for(const t of state.tasks.filter(t=>t.status!=='done'&&t.due)){const time=new Date(t.due+'T08:00:00').getTime();if(time>Date.now())items.push({id:t.id,time});}for(const e of state.events){const time=new Date(e.start).getTime()-15*60000;if(time>Date.now())items.push({id:e.id,time});}if(state.profile.focusSession)items.push({id:'focus-session',time:state.profile.focusSession.end});await call('reminders.schedule',{items:items.slice(0,200)});}
function connectionIndicator(){updateWorkspaceStatus();const el=$('connectionIndicator');if(!el)return;el.dataset.mode=connection.mode;el.textContent=connection.mode==='connected'?(connection.available?'Online mode':'Online mode · No internet'):'Offline mode';if(window.I18n)I18n.apply();}
function requireConnected(){if(connection.mode!=='connected')throw Error('Enable Connected mode in Settings → Offline / Connected services. Your local tools work in either mode.');}
