 if(name==='localTutor'||name==='quickAnswer'){const question=$('materialQuery').value.trim();if(!question)throw Error('Enter a question first.');const answer=Student.sourceAnswer(state,question,studyCourse,studyKeys);showReader('Answer from your materials',`<p class="muted small">${name==='localTutor'?'Prepared local model draft — no API key or credits. Verify all claims against the source excerpts.':'Quick extractive answer — copied source evidence, not a generated explanation.'}</p><div id="localAnswer" class="quote">${esc(answer.text)}</div>${answerSources(answer)}`);if(name==='localTutor'&&answer.found){try{const response=await call('local.answer',{question,sources:answer.context,language:state.profile.uiLanguage||'en'});if($('localAnswer'))$('localAnswer').textContent=response.text;}catch(e){notify(e.message+' Source answer remains available.',true);}}return;}
 if(name==='documentOcr'){const d=state.documents.find(x=>x.id===id),r=await call('document.ocr',{id,page:docPage});editForm('Review offline OCR',[field('text','Check words, numbers and formulas','textarea',r.text)],v=>{d.text=[d.text,'[Page '+(docPage+1)+']\n'+v.text].filter(Boolean).join('\n\n');audit('Saved reviewed offline page text');});return;}
 if(name==='handOcr'){const n=handNote(),r=await call('ocr.image',{image:Handwriting.png(n)});editForm('Review handwriting text',[field('text','Correct unclear handwriting before study','textarea',r.text)],v=>{n.text=v.text;audit('Saved reviewed offline handwriting text');});return;}
 if(name==='accountDetails'){navigate('settings');$('accountDetails')?.scrollIntoView({block:'start'});return;}
 if(name==='fontSmaller'||name==='fontLarger'||name==='fontPreset'){const value=name==='fontPreset'?Number(id):Student.textSize(state.profile.fontSize)+(name==='fontLarger'?1:-1);setTextSize(Math.max(14,Math.min(24,value)));await persist();return;}
 if(name==='resetAppearance'){if(await confirmation('Reset appearance and shortcuts?','Restore 16 px text, light theme and Today / Planner / Study / Write shortcuts. Your notes, recordings, courses, account and connection settings will be kept.','Reset appearance')){state.profile.fontSize=16;state.profile.theme='light';state.profile.favorites=Student.favorites();applyPreferences();await persist();render();notify('Appearance and shortcuts reset. Your study data is kept.');}return;}
 if(name==='quickNav'){navigate(id,id==='planner'?'tasks':id==='study'?'library':undefined);return;}
 if(name==='manageFavorites'){favoriteManager();return;}
